public boolean move(@Nonnull Frame frame, @Nonnull SelectionPresenter opsState, @Nonnull float[] sceneTouch) {
    if (this.mIgnoreMoveUntilUp) {
        return true;
    }
    float f = sceneTouch[0];
    float f2 = sceneTouch[1];
    if (opsState.mPointer != null) {
        opsState.mPointer.set(f, f2);
    }
    TouchDownResult touchDownResult = opsState.mTouchDownResult;
    if (touchDownResult.isFruitless()) {
        return false;
    }
    final UPoint uPoint = opsState.capturedPoint(frame).get();
    Unit unitOrNull = opsState.getActiveUnit(frame).orNull();
    if (unitOrNull != null && isUnitLockedInSelection(frame.getScene(), unitOrNull.getName())) {
        return false;
    }
    try {
        if (TransformingHandlersPresenter.isHandlerPoint(uPoint.getId())) {
            opsState.handlersPresenter().getHandlerById(uPoint.getId()).move(uPoint, f, f2);
        } else {
            final float f3 = f - touchDownResult.mTouchOffset[0];
            final float f4 = f2 - touchDownResult.mTouchOffset[1];
            frame.getScene().selectedRange().apply(opsState.getActiveUnit(frame).get().getName(), new IUnitOp() { // from class: ru.jecklandin.stickman.features.editor.widgets.usecases.TouchPointUseCase$$ExternalSyntheticLambda2
                @Override // ru.jecklandin.stickman.units.IUnitOp
                public final void apply(Unit unit) {
                    PointManipulator.move(unit, unit.findPointById(uPoint.getId()), f3, f4);
                }
            });
        }
        return true;
    } catch (IllegalStateException e) {
        notifyAutoTweenLocked(e);
        return false;
    }
}
